package main

import (
	"fmt"
	"net"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/kimjindol2025/fl-httpd/internal/compiler"
	"github.com/kimjindol2025/fl-httpd/internal/conn"
	"github.com/kimjindol2025/fl-httpd/internal/http"
	"github.com/kimjindol2025/fl-httpd/internal/middleware"
	"github.com/kimjindol2025/fl-httpd/internal/router"
)

func main() {
	// Default port
	port := ":8080"
	if len(os.Args) > 1 {
		port = os.Args[1]
	}

	// Create router and register handlers
	r := router.NewRouter()

	// Create FreeLang compiler
	flCompiler := compiler.NewFreeLangCompiler("/data/data/com.termux/files/home/v2-archive/freelang-v2/dist/cli.js")
	flCompiler.SetTimeout(10 * time.Second)

	// Health check endpoint
	r.GET("/health", func(req *http.Request, res *http.Response) {
		res.StatusCode = 200
		res.Status = "OK"
		res.SetBodyString("OK")
	})

	// Root endpoint
	r.GET("/", func(req *http.Request, res *http.Response) {
		res.StatusCode = 200
		res.Status = "OK"
		body := `
<!DOCTYPE html>
<html>
<head>
  <title>FreeLang HTTP Server</title>
  <style>
    body { font-family: monospace; margin: 20px; }
    .code { background: #f0f0f0; padding: 10px; border-radius: 5px; }
  </style>
</head>
<body>
  <h1>🚀 FreeLang HTTP/1.1 Server</h1>
  <p>Zero-Dependency HTTP Server (TCP → RFC 7230)</p>
  <div class="code">
    GET /health → Health check
    GET /api/info → Server info
  </div>
</body>
</html>
`
		res.SetBodyString(body)
		res.SetHeader("Content-Type", "text/html; charset=utf-8")
	})

	// API info endpoint
	r.GET("/api/info", func(req *http.Request, res *http.Response) {
		res.StatusCode = 200
		res.Status = "OK"
		flStatus := "unavailable"
		if flCompiler.IsAvailable() {
			flStatus = "available"
		}
		body := fmt.Sprintf(`{
  "server": "freelang-server",
  "version": "1.0.0",
  "status": "running",
  "dependencies": 0,
  "backend": "pure Go stdlib (net, bufio, strings, sync)",
  "freelang": {
    "status": "%s",
    "available": %v
  }
}
`, flStatus, flCompiler.IsAvailable())
		res.SetBodyString(body)
		res.SetHeader("Content-Type", "application/json")
	})

	// Compile API endpoint (POST /api/compile)
	// Returns mock response for now (FreeLang CLI requires full Node.js environment)
	r.POST("/api/compile", func(req *http.Request, res *http.Response) {
		// Extract code from body
		code := string(req.Body)
		if code == "" {
			res.StatusCode = 400
			res.Status = "Bad Request"
			res.SetBodyString(`{"error": "Code is required in request body"}`)
			res.SetHeader("Content-Type", "application/json")
			return
		}

		// For now, return mock compilation result
		// In production, this would call the actual FreeLang compiler
		body := fmt.Sprintf(`{
  "success": true,
  "output": "Code compiled successfully\\n[Mock Output - FreeLang CLI integration pending]\\n",
  "error": "",
  "duration_ms": 45,
  "bytes_used": %d,
  "note": "Full compilation requires npm-based FreeLang deployment. Currently in mock mode."
}
`, len(code))

		res.StatusCode = 200
		res.Status = "OK"
		res.SetBodyString(body)
		res.SetHeader("Content-Type", "application/json")
	})

	// Create logger
	logger := middleware.NewLogger(true)

	// Listen for connections
	listener, err := net.Listen("tcp", port)
	if err != nil {
		fmt.Printf("❌ Failed to listen on %s: %v\n", port, err)
		os.Exit(1)
	}
	defer listener.Close()

	fmt.Printf("✅ Server listening on http://localhost%s\n", port)
	fmt.Printf("   Health: http://localhost%s/health\n", port)
	fmt.Printf("   Info: http://localhost%s/api/info\n", port)

	// Connection pool for graceful shutdown
	var connWg sync.WaitGroup
	stopChan := make(chan struct{})

	// Accept loop in a goroutine
	go func() {
		for {
			select {
			case <-stopChan:
				return
			default:
			}

			netConn, err := listener.Accept()
			if err != nil {
				select {
				case <-stopChan:
					return
				default:
					fmt.Printf("Accept error: %v\n", err)
					continue
				}
			}

			connWg.Add(1)
			go func(netConn net.Conn) {
				defer connWg.Done()

				// Wrap connection with Keep-Alive handler
				ch := conn.NewConnectionHandler(netConn)
				ch.SetKeepAliveTimeout(30 * time.Second)
				ch.SetReadTimeout(15 * time.Second)
				ch.SetWriteTimeout(15 * time.Second)

				logger.LogConnectionOpen(ch.RemoteAddr())
				startTime := time.Now()
				requestCount := 0

				// Create a wrapped request handler
				wrappedHandler := func(req *http.Request, res *http.Response) {
					requestCount++
					reqStartTime := time.Now()

					// Route request
					r.Handle(req, res)

					// Set standard headers
					if res.GetHeader("Content-Type") == "" {
						res.SetHeader("Content-Type", "text/plain")
					}

					// Log request
					duration := time.Since(reqStartTime)
					logger.Log(ch.RemoteAddr(), req, res, duration)
				}

				// Handle the connection (Keep-Alive loop inside)
				ch.HandleConnection(wrappedHandler)

				// Log connection close
				duration := time.Since(startTime)
				logger.LogConnectionClose(ch.RemoteAddr(), requestCount, duration)
			}(netConn)
		}
	}()

	// Wait for interrupt signal
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
	<-sigChan

	fmt.Println("\n🛑 Graceful shutdown starting...")
	fmt.Println("⏳ Waiting for active connections to close...")

	// Signal accept loop to stop
	close(stopChan)

	// Wait for all connections to finish (with timeout)
	done := make(chan struct{})
	go func() {
		connWg.Wait()
		close(done)
	}()

	select {
	case <-done:
		fmt.Println("✅ Server stopped gracefully")
	case <-time.After(5 * time.Second):
		fmt.Println("⚠️ Shutdown timeout - forcing close")
	}
}

package router

import (
	"fmt"
	"strings"
	"sync"

	"github.com/kimjindol2025/fl-httpd/internal/http"
)

// HandlerFunc is the signature for HTTP handlers
type HandlerFunc func(req *http.Request, res *http.Response)

// Route represents a single route
type Route struct {
	Method  string
	Path    string
	Handler HandlerFunc
}

// Router handles HTTP routing
type Router struct {
	routes []Route
	mu     sync.RWMutex
}

// NewRouter creates a new router
func NewRouter() *Router {
	return &Router{
		routes: []Route{},
	}
}

// GET registers a GET handler
func (r *Router) GET(path string, handler HandlerFunc) {
	r.Register("GET", path, handler)
}

// POST registers a POST handler
func (r *Router) POST(path string, handler HandlerFunc) {
	r.Register("POST", path, handler)
}

// PUT registers a PUT handler
func (r *Router) PUT(path string, handler HandlerFunc) {
	r.Register("PUT", path, handler)
}

// DELETE registers a DELETE handler
func (r *Router) DELETE(path string, handler HandlerFunc) {
	r.Register("DELETE", path, handler)
}

// Register registers a route with method and path
func (r *Router) Register(method, path string, handler HandlerFunc) {
	r.mu.Lock()
	defer r.mu.Unlock()

	r.routes = append(r.routes, Route{
		Method:  strings.ToUpper(method),
		Path:    path,
		Handler: handler,
	})

	fmt.Printf("[Router] Registered %s %s\n", method, path)
}

// Handle matches a request to a handler and executes it
func (r *Router) Handle(req *http.Request, res *http.Response) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	// Find matching route
	for _, route := range r.routes {
		if route.Method == req.Method && r.matchPath(route.Path, req.Path) {
			route.Handler(req, res)
			return
		}
	}

	// No route found
	res.StatusCode = 404
	res.Status = "Not Found"
	res.SetBodyString("404 Not Found")
}

// matchPath checks if a route path matches a request path
// Simple exact match for now (can be extended for patterns like /users/:id)
func (r *Router) matchPath(routePath, reqPath string) bool {
	// Exact match
	if routePath == reqPath {
		return true
	}

	// TODO: Add pattern matching (e.g., /users/:id)
	return false
}

// ListRoutes returns all registered routes
func (r *Router) ListRoutes() []Route {
	r.mu.RLock()
	defer r.mu.RUnlock()

	routes := make([]Route, len(r.routes))
	copy(routes, r.routes)
	return routes
}

